<script setup lang="ts">
import {computed,reactive,ref,onMounted,watch} from 'vue'
import {api,user,refreshAuth,siteName,message,notify} from '../api'
const error=ref(''),ready=ref(false),saving=ref(false),accounts=ref<any[]>([]),publicAccounts=ref<any[]>([]),qqs=ref<any[]>([]),catalog=ref<Record<string,string>>({}),tab=ref('概览'),importText=ref(''),editing=ref<any>(null),publicEditing=ref<any>(null),search=ref(''),memberSearch=ref('')
const qqGroups=ref<{groupId:string;count:number}[]>([]),currentGroup=ref(''),qqSearch=ref('')
const groupQqs=computed(()=>qqs.value.filter(q=>q.groupId===currentGroup.value&&`${q.qqNumber} ${q.name}`.toLowerCase().includes(qqSearch.value.trim().toLowerCase())))
const availableQqs=computed(()=>new Set(qqs.value.filter(q=>q.active&&!q.bound).map(q=>q.qqNumber)).size)
const form=reactive({siteName:'',siteDescription:'',registrationEnabled:true,registrationMode:'test'})
const isSuper=computed(()=> (user.value?.actorRole||user.value?.role)==='SUPER_ADMIN')
const personalAccounts=computed(()=>accounts.value.filter(m=>m.accountType!=='PUBLIC'))
const filteredAccounts=computed(()=>personalAccounts.value.filter(m=>`${m.username} ${m.penName}`.toLowerCase().includes(search.value.trim().toLowerCase())))
const filteredMembers=computed(()=>personalAccounts.value.filter(m=>`${m.username} ${m.penName}`.toLowerCase().includes(memberSearch.value.trim().toLowerCase())))
const roles:Record<string,string>={SUPER_ADMIN:'超级管理员',ADMIN:'管理员',MEMBER:'社员',RESTRICTED:'受限社员'}
function roleLabel(role:string){return roles[role]||role}
function canEdit(m:any){return isSuper.value||!['SUPER_ADMIN','ADMIN'].includes(m.role)}
async function load(){error.value='';try{const [s,a,q,p,g]=await Promise.all([api.get('/admin/settings'),api.get('/admin/accounts'),api.get('/admin/registration/qq-allowlist'),api.get('/admin/public-accounts'),api.get('/admin/registration/qq-groups')]);Object.assign(form,s.data);catalog.value=s.data.permissionCatalog;accounts.value=a.data;qqs.value=q.data;publicAccounts.value=p.data;qqGroups.value=g.data;if(!qqGroups.value.some(group=>group.groupId===currentGroup.value))currentGroup.value=qqGroups.value[0]?.groupId||'';ready.value=true}catch(e){error.value=message(e)}}
async function save(){saving.value=true;error.value='';try{await api.put('/admin/settings',form);siteName.value=form.siteName;notify('后台配置已保存')}catch(e){error.value=message(e)}finally{saving.value=false}}
async function edit(id:number){error.value='';try{editing.value=(await api.get(`/admin/accounts/${id}/permissions`)).data}catch(e){error.value=message(e)}}
async function savePermissions(){if(!editing.value)return;saving.value=true;error.value='';try{const id=editing.value.id;await api.put(`/admin/accounts/${id}/permissions`,editing.value);editing.value=null;notify('账号权限已更新');await refreshAuth();if(['ADMIN','SUPER_ADMIN'].includes(user.value?.actorRole||user.value?.role||''))await load()}catch(e){error.value=message(e)}finally{saving.value=false}}
function editPublic(account:any){publicEditing.value={...account,memberIds:[...account.memberIds]};memberSearch.value='';error.value=''}
async function savePublic(){if(!publicEditing.value)return;saving.value=true;error.value='';try{await api.put(`/admin/public-accounts/${publicEditing.value.id}/members`,{memberIds:publicEditing.value.memberIds});publicEditing.value=null;notify('授权名单已更新');await load()}catch(e){error.value=message(e)}finally{saving.value=false}}
async function importQqs(){saving.value=true;error.value='';try{const qqNumbers=importText.value.split(/[\s,，;；]+/).filter(Boolean);const r=await api.post('/admin/registration/qq-allowlist',{groupId:currentGroup.value,qqNumbers});importText.value='';notify(`已启用 ${r.data.count} 个 QQ 号`);await load()}catch(e){error.value=message(e)}finally{saving.value=false}}
async function disable(qq:string){try{await api.delete(`/admin/registration/qq-allowlist/${encodeURIComponent(currentGroup.value)}/${qq}`);await load()}catch(e){error.value=message(e)}}
async function enable(qq:string){try{await api.post('/admin/registration/qq-allowlist',{groupId:currentGroup.value,qqNumbers:[qq]});await load()}catch(e){error.value=message(e)}}
watch(()=>editing.value?.role,(role,previous)=>{if(!previous||role===previous||!editing.value)return;if(role==='RESTRICTED'||(previous==='RESTRICTED'&&role==='MEMBER'))for(const key of Object.keys(catalog.value))editing.value.permissions[key]=role==='MEMBER'})
function selectTab(value:string){tab.value=value;error.value='';editing.value=null;publicEditing.value=null}
onMounted(load)
</script>
<template><div class="container page-space admin-settings"><div class="section-heading"><div><p class="eyebrow">管理 / 配置</p><h1 class="page-title">后台配置</h1><p class="page-description">管理个人账号、公用身份和注册设置。</p></div><RouterLink to="/admin" class="text-button">返回社务台 →</RouterLink></div><div class="genre-tabs desk-tabs admin-tabs"><button v-for="t in ['概览','账号与权限','公用账号','站点与注册','QQ 号库']" :key="t" :class="{selected:tab===t}" @click="selectTab(t)">{{t}}</button></div><p v-if="error" class="error-message" role="alert">{{error}}</p><p v-if="!ready&&!error" class="quiet-note">加载中…</p><template v-if="ready">
 <section v-if="tab==='概览'" class="admin-overview"><div class="admin-overview-grid"><button class="admin-overview-card" @click="selectTab('账号与权限')"><strong>{{personalAccounts.length}}</strong><span>个人账号</span><small>角色与功能权限 →</small></button><button class="admin-overview-card" @click="selectTab('公用账号')"><strong>{{publicAccounts.length}}</strong><span>公用账号</span><small>身份与授权名单 →</small></button><button class="admin-overview-card" @click="selectTab('QQ 号库')"><strong>{{availableQqs}}</strong><span>可用 QQ 号</span><small>注册名单 →</small></button></div><div class="panel admin-overview-links"><h2>常用管理</h2><RouterLink to="/admin">稿件、社员与活动标签 →</RouterLink><button type="button" @click="selectTab('站点与注册')">网站名称与注册设置 →</button></div></section>
 <template v-else-if="tab==='账号与权限'"><div class="admin-toolbar"><p class="quiet-note">管理员管理社员及受限账号；超级管理员还可调整管理员角色。</p><label class="admin-search"><span class="sr-only">搜索账号</span><input v-model="search" placeholder="搜索账号或笔名"/></label></div><div class="table-wrap"><table><thead><tr><th>账号</th><th>笔名</th><th>角色</th><th></th></tr></thead><tbody><tr v-for="m in filteredAccounts" :key="m.id"><td>{{m.username}}</td><td>{{m.penName}}</td><td>{{roleLabel(m.role)}}</td><td><button v-if="canEdit(m)" @click="edit(m.id)">配置权限</button><span v-else class="quiet-note">仅超级管理员可管理</span></td></tr></tbody></table><p v-if="!filteredAccounts.length" class="quiet-note">没有匹配的账号</p></div><form v-if="editing" class="panel permission-editor" @submit.prevent="savePermissions"><h3>配置 {{editing.username}}</h3><label>账号角色<select v-model="editing.role"><option value="MEMBER">社员</option><option value="RESTRICTED">受限社员</option><template v-if="isSuper"><option value="ADMIN">管理员</option><option value="SUPER_ADMIN">超级管理员</option></template></select></label><p class="quiet-note">受限社员默认关闭投稿、评论、上传、合集和点赞收藏五项权限，可按需单独恢复；管理员拥有全部功能权限。</p><label v-for="(label,code) in catalog" :key="code" class="checkbox-label"><input type="checkbox" v-model="editing.permissions[code]" :disabled="['ADMIN','SUPER_ADMIN'].includes(editing.role)"/>{{label}}</label><div class="permission-actions"><button class="button" :disabled="saving">保存权限</button><button type="button" class="text-button" @click="editing=null">取消</button></div></form></template>
 <template v-else-if="tab==='公用账号'"><p class="quiet-note">白名单中的个人账号可切换为对应公用身份；每个公用账号最多同时由 5 名个人使用。白名单人数不限。</p><div class="admin-public-grid"><article v-for="account in publicAccounts" :key="account.id" class="panel admin-public-card"><div><h2>{{account.penName}} <span class="verified-badge">认证</span></h2><p>{{account.memberIds.length}} 人已授权</p></div><button type="button" class="button secondary small" @click="editPublic(account)">{{isSuper?'管理授权':'查看名单'}}</button></article></div><form v-if="publicEditing" class="panel permission-editor" @submit.prevent="savePublic"><h3>{{publicEditing.penName}} · 授权名单</h3><p class="quiet-note">授权后，社员可在登录时选择该公用身份。</p><label class="admin-search"><span class="sr-only">搜索成员</span><input v-model="memberSearch" placeholder="搜索账号或笔名"/></label><div class="public-member-list"><label v-for="m in filteredMembers" :key="m.id" class="checkbox-label"><input type="checkbox" :value="m.id" v-model="publicEditing.memberIds" :disabled="!isSuper"/><span>{{m.penName}} <small>{{m.username}} · {{roleLabel(m.role)}}</small></span></label><p v-if="!filteredMembers.length" class="quiet-note">没有匹配的账号</p></div><div class="permission-actions"><button v-if="isSuper" class="button" :disabled="saving">保存名单</button><button type="button" class="text-button" @click="publicEditing=null">关闭</button></div></form></template>
 <form v-else-if="tab==='站点与注册'" class="panel profile-form" @submit.prevent="save"><label>站点名称<input v-model="form.siteName" maxlength="80" required/></label><label>站点介绍<textarea v-model="form.siteDescription" maxlength="300" rows="3"></textarea></label><label class="checkbox-label"><input v-model="form.registrationEnabled" type="checkbox"/>开放注册</label><label>测试账号<select v-model="form.registrationMode"><option value="test">启用（12345 / 0000）</option><option value="live">停用测试账号</option></select></label><p class="quiet-note">本地名单中的 QQ 号通过同名 QQ 邮箱接收验证码；测试账号不发送邮件。</p><button class="button" :disabled="saving">保存配置</button></form>
 <template v-else><div class="panel profile-form"><label>选择群号<select v-model="currentGroup"><option v-for="group in qqGroups" :key="group.groupId" :value="group.groupId">{{group.groupId}}（{{group.count}} 人）</option></select></label><p v-if="!qqGroups.length" class="quiet-note">请在 QQ_Whitelist 中按群号创建 Markdown 名单文件。</p><p class="quiet-note">每个群对应一个 Markdown 文件。相同 QQ 在所有群中的启用及绑定状态同步。若群昵称不同，注册默认采用群号排序靠前的名称；名单文件修改后点击刷新。</p><div class="permission-actions"><button type="button" class="button secondary small" @click="load">刷新名单</button><label class="admin-search"><span class="sr-only">搜索 QQ 或昵称</span><input v-model="qqSearch" placeholder="搜索 QQ 号或昵称"/></label></div></div><form v-if="currentGroup" class="panel profile-form" @submit.prevent="importQqs"><label>启用当前群名单中的 QQ 号<textarea v-model="importText" rows="3" placeholder="输入已在当前群文件中的 QQ 号，可用逗号或换行分隔。" required></textarea></label><button class="button" :disabled="saving">启用 QQ 号</button></form><div v-if="currentGroup" class="table-wrap"><table><thead><tr><th>QQ 号</th><th>群内名称</th><th>状态</th><th></th></tr></thead><tbody><tr v-for="q in groupQqs" :key="q.groupId+q.qqNumber"><td>{{q.qqNumber}}</td><td>{{q.name}}</td><td>{{q.bound?'已绑定':q.active?'可注册':'已停用'}}</td><td><button v-if="q.active" @click="disable(q.qqNumber)">停用</button><button v-else @click="enable(q.qqNumber)">启用</button></td></tr></tbody></table><p v-if="!groupQqs.length" class="quiet-note">当前群没有匹配的账号。</p></div></template> </template></div></template>
